   305→bool USessionManager::StartSession()
   306→{
   307→	if (!SessionInterface.IsValid())
   308→	{
   309→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   310→		return false;
   311→	}
   312→
   313→	if (!bIsHost)
   314→	{
