   333→bool USessionManager::EndSession()
   334→{
   335→	if (!SessionInterface.IsValid())
   336→	{
   337→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   338→		return false;
   339→	}
   340→
   341→	// 세션이 존재하고 InProgress 상태인지 확인
   342→	FNamedOnlineSession* ExistingSession = SessionInterface->GetNamedSession(SESSION_NAME);
   343→	if (!ExistingSession)
   344→	{
   345→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: EndSession - No session exists"));
   346→		return false;
   347→	}
   348→
   349→	if (ExistingSession->SessionState != EOnlineSessionState::InProgress)
   350→	{
   351→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: EndSession - Session not InProgress (state: %d), skipping"),
   352→			static_cast<int32>(ExistingSession->SessionState));
   353→		return true; // 이미 종료된 상태이므로 성공으로 간주
   354→	}
   355→
   356→	bool bSuccess = SessionInterface->EndSession(SESSION_NAME);
   357→
   358→	if (bSuccess)
   359→	{
   360→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Ending session (InProgress → Ended)"));
   361→	}
   362→	else
   363→	{
   364→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to end session"));
   365→	}
   366→
   367→	return bSuccess;
   368→}
