   370→bool USessionManager::DestroySession()
   371→{
   372→	if (!SessionInterface.IsValid())
   373→	{
   374→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   375→		return false;
   376→	}
   377→
   378→	bool bSuccess = SessionInterface->DestroySession(SESSION_NAME);
   379→
   380→	if (bSuccess)
   381→	{
   382→		bIsInSession = false;
   383→		bIsHost = false;
   384→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Destroying session"));
   385→	}
   386→	else
   387→	{
   388→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to destroy session"));
   389→	}
   390→
   391→	return bSuccess;
