   394→void USessionManager::OnCreateSessionComplete(FName SessionName, bool bWasSuccessful)
   395→{
   396→	UE_LOG(LogWjWorld, Log, TEXT("SessionManager: OnCreateSessionComplete - Success: %d, SessionName: %s"), bWasSuccessful, *SessionName.ToString());
   397→
   398→	if (bWasSuccessful)
   399→	{
   400→		bIsInSession = true;
   401→		bIsHost = true;
   402→	}
   403→
   404→	OnRoomCreatedEvent.Broadcast(bWasSuccessful);
