   606→	SessionSettings.NumPublicConnections = Settings.MaxPlayers;
   607→	SessionSettings.bShouldAdvertise = true;
   608→	SessionSettings.bAllowJoinInProgress = true;
   609→	SessionSettings.bAllowJoinViaPresence = false;
   610→	SessionSettings.bAllowJoinViaPresenceFriendsOnly = false;
   611→
   612→	// 네트워크 모드에 따른 설정
   613→	// Steam: bUsesPresence와 bUseLobbiesIfAvailable은 반드시 같은 값이어야 함
   614→	if (Settings.NetworkMode == ENetworkMode::Steam)
   615→	{
   616→		SessionSettings.bIsLANMatch = false;
   617→		SessionSettings.bUsesPresence = true;
   618→		SessionSettings.bUseLobbiesIfAvailable = true;
   619→	}
   620→	else // LAN
   621→	{
   622→		SessionSettings.bIsLANMatch = true;
   623→		SessionSettings.bUsesPresence = false;
   624→		SessionSettings.bUseLobbiesIfAvailable = false;
   625→	}
   626→
   627→	// 커스텀 데이터 설정
   628→	SessionSettings.Set(FName("ROOM_NAME"), Settings.RoomName, EOnlineDataAdvertisementType::ViaOnlineService);
   629→	SessionSettings.Set(FName("GAME_MODE"), Settings.GameMode, EOnlineDataAdvertisementType::ViaOnlineService);
   630→	SessionSettings.Set(FName("MAP_NAME"), Settings.MapName, EOnlineDataAdvertisementType::ViaOnlineService);
   631→	SessionSettings.Set(FName("IS_PRIVATE"), Settings.bIsPrivate, EOnlineDataAdvertisementType::ViaOnlineService);
