	const FOnlineSessionSearchResult& Result = SessionSearch->SearchResults[SearchResultIndex];
	bool bFound = Result.Session.SessionSettings.Get(FName("PASSWORD"), OutPassword);

	return bFound && !OutPassword.IsEmpty();
}

