	// 버튼 이벤트 바인딩
	if (JoinButton)
	{
		JoinButton->OnClicked.AddDynamic(this, &URoomListEntryWidget::OnJoinClicked);
	}

	// SessionManager 델리게이트 바인딩
	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
