    65→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: GameState found! PlayerCount = %d"), PlayerCount);
    66→		
    67→		// PlayerArray 내용 확인
    68→		for (int32 i = 0; i < CachedGameState->PlayerArray.Num(); i++)
    69→		{
    70→			APlayerState* PS = CachedGameState->PlayerArray[i];
    71→			if (PS)
    72→			{
    73→				UE_LOG(LogWjWorld, Warning, TEXT("  - PlayerState[%d]: %s (ID: %d)"), 
    74→					i, *PS->GetPlayerName(), PS->GetPlayerId());
    75→			}
    76→		}
    77→
    78→		// 델리게이트 바인딩
    79→		CachedGameState->OnRoomInfoChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnRoomInfoChanged);
    80→		CachedGameState->OnPlayerListChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnPlayerListChanged);
    81→
    82→		// 초기 데이터 로드
    83→		UpdateRoomInfo();
    84→		UpdatePlayerList();
    85→		UpdateStartGameButton();
    86→		UpdateReadyButton();
    87→
    88→		// 호스트 설정 패널 초기화
    89→		InitializeHostSettingsPanel();
    90→		UpdateHostSettingsPanelVisibility();
    91→
    92→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: GameState events bound"));
    93→	}
    94→	else
    95→	{
    96→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: Failed to get GameStateWaitingRoom"));
    97→	}
    98→
    99→	// PlayerState 이벤트 바인딩
   100→	APlayerController* PC = GetOwningPlayer();
   101→	if (PC)
   102→	{
   103→		AWjWorldPlayerStateBase* PlayerState = PC->GetPlayerState<AWjWorldPlayerStateBase>();
   104→		if (PlayerState)
   105→		{
   106→			PlayerState->OnReadyStateChanged.AddDynamic(this, &UWaitingRoomHUDWidget::OnPlayerReadyStateChanged);
   107→			UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: PlayerState events bound - %s"), *PlayerState->GetPlayerName());
   108→		}
   109→		else
   110→		{
   111→			UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: PlayerState is NULL"));
   112→		}
   113→	}
   114→
   115→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget: NativeConstruct END ==="));
   116→}
