   292→void UWaitingRoomHUDWidget::UpdateRoomInfo(const FRoomSettings* InSettings)
   293→{
   294→	// 설정이 직접 전달되면 사용, 아니면 GameState에서 읽음
   295→	FRoomSettings Settings;
   296→	if (InSettings)
   297→	{
   298→		Settings = *InSettings;
   299→	}
   300→	else if (CachedGameState)
   301→	{
   302→		Settings = CachedGameState->GetRoomSettings();
   303→	}
   304→	else
   305→	{
   306→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdateRoomInfo - CachedGameState is NULL"));
   307→		return;
   308→	}
   309→
   310→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdateRoomInfo - Updating with: RoomName='%s', GameMode='%s', MapName='%s'"),
   311→		*Settings.RoomName, *Settings.GameMode, *Settings.MapName);
   312→
   313→	// 방 이름 표시
   314→	if (RoomNameText)
   315→	{
   316→		RoomNameText->SetText(FText::FromString(Settings.RoomName));
   317→	}
   318→
   319→	// 게임 모드 표시
   320→	if (GameModeText)
   321→	{
   322→		GameModeText->SetText(FText::FromString(Settings.GameMode));
   323→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: GameModeText set to '%s'"), *Settings.GameMode);
   324→	}
   325→
   326→	// 맵 이름 표시
   327→	if (MapText)
   328→	{
   329→		FString MapDisplayName = Settings.MapName;
   330→		// User_ 접두사 제거하여 표시
   331→		MapDisplayName.RemoveFromStart(TEXT("User_"));
   332→		MapText->SetText(FText::FromString(MapDisplayName));
   333→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: MapText set to '%s'"), *MapDisplayName);
   334→	}
   335→
   336→	// ⭐ 플레이어 수 표시 (실시간으로 가져오기)
   337→	if (PlayerCountText && CachedGameState)
   338→	{
   339→		int32 CurrentPlayers = CachedGameState->GetPlayerCount();
   340→		int32 MaxPlayers = Settings.MaxPlayers;
   341→
   342→		FString PlayerCountStr = FString::Printf(TEXT("%d / %d"), CurrentPlayers, MaxPlayers);
   343→		PlayerCountText->SetText(FText::FromString(PlayerCountStr));
   344→
   345→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: PlayerCountText set to '%s'"), *PlayerCountStr);
   346→	}
   347→
   348→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Room info updated successfully"));
   349→}
