   351→void UWaitingRoomHUDWidget::UpdatePlayerList()
   352→{
   353→	if (!CachedGameState || !PlayerListContainer)
   354→	{
   355→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget::UpdatePlayerList - GameState or Container is NULL"));
   356→		return;
   357→	}
   358→
   359→	// 기존 목록 제거
   360→	PlayerListContainer->ClearChildren();
   361→	PlayerButtonToIDMap.Empty();
   362→
   363→	// 플레이어 목록 가져오기 & 캐시
   364→	CachedPlayerDisplayList = CachedGameState->GetPlayerList();
   365→
   366→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Updating player list - %d players"), CachedPlayerDisplayList.Num());
   367→
   368→	// 버튼으로 표시 (클릭 시 프로필 팝업)
   369→	for (const FPlayerDisplayInfo& Info : CachedPlayerDisplayList)
   370→	{
   371→		UButton* PlayerButton = NewObject<UButton>(this);
   372→		if (!PlayerButton)
   373→		{
   374→			continue;
   375→		}
   376→
   377→		// 버튼 안에 텍스트 추가
   378→		UTextBlock* PlayerText = NewObject<UTextBlock>(this);
   379→		if (PlayerText)
   380→		{
   381→			FString DisplayText = Info.PlayerName;
   382→
   383→			if (Info.bIsHost)
   384→			{
   385→				DisplayText = FString::Printf(TEXT("[Host] %s"), *DisplayText);
   386→			}
   387→
   388→			if (Info.bIsReady)
   389→			{
   390→				DisplayText += TEXT(" (Ready)");
   391→			}
   392→
   393→			PlayerText->SetText(FText::FromString(DisplayText));
   394→			PlayerButton->AddChild(PlayerText);
   395→		}
   396→
   397→		// 버튼 → PlayerID 매핑 저장
   398→		PlayerButtonToIDMap.Add(PlayerButton, Info.PlayerID);
   399→
   400→		// 모든 버튼에 공통 핸들러 바인딩
   401→		PlayerButton->OnClicked.AddDynamic(this, &UWaitingRoomHUDWidget::OnAnyPlayerButtonClicked);
   402→
   403→		PlayerListContainer->AddChild(PlayerButton);
   404→
   405→		UE_LOG(LogWjWorld, Warning, TEXT("  - %s (ID: %d)"), *Info.PlayerName, Info.PlayerID);
   406→	}
   407→}
