   530→void UWaitingRoomHUDWidget::UpdateStartGameButton()
   531→{
   532→	if (!StartGameButton || !CachedGameState)
   533→	{
   534→		return;
   535→	}
   536→
   537→	// 호스트 여부 확인
   538→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   539→	if (!GameInstance || !GameInstance->GetSessionManager())
   540→	{
   541→		return;
   542→	}
   543→
   544→	bool bIsHost = GameInstance->GetSessionManager()->IsHost();
   545→	
   546→	if (bIsHost)
   547→	{
   548→		// 호스트는 모든 플레이어가 준비되었을 때만 게임 시작 가능
   549→		bool bAllReady = CachedGameState->AreAllPlayersReady();
   550→		int32 PlayerCount = CachedGameState->GetPlayerCount();
   551→
   552→		// 카탈로그에서 최소 인원 조회
   553→		int32 MinPlayers = 1;
   554→		const FRoomSettings& CurrentSettings = CachedGameState->GetRoomSettings();
   555→		const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   556→		if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
   557→		{
   558→			UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   559→			if (Catalog)
   560→			{
   561→				const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*CurrentSettings.GameMode));
   562→				if (Def)
   563→				{
   564→					MinPlayers = Def->MinimumPlayers;
   565→				}
   566→			}
   567→		}
   568→
   569→		bool bEnoughPlayers = (PlayerCount >= MinPlayers);
   570→		bool bCanStart = bAllReady && bEnoughPlayers;
   571→
   572→		StartGameButton->SetIsEnabled(bCanStart);
   573→
   574→		// 시작 불가 사유 표시
   575→		if (StartGameStatusText)
   576→		{
   577→			if (!bEnoughPlayers)
   578→			{
   579→				StartGameStatusText->SetText(FText::FromString(
   580→					FString::Printf(TEXT("Need %d+ players (%d/%d)"), MinPlayers, PlayerCount, MinPlayers)));
   581→				StartGameStatusText->SetVisibility(ESlateVisibility::Visible);
   582→			}
   583→			else if (!bAllReady)
   584→			{
   585→				StartGameStatusText->SetText(FText::FromString(TEXT("Waiting for all players to ready")));
   586→				StartGameStatusText->SetVisibility(ESlateVisibility::Visible);
   587→			}
   588→			else
   589→			{
   590→				StartGameStatusText->SetVisibility(ESlateVisibility::Collapsed);
   591→			}
   592→		}
   593→
   594→		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Start button enabled = %d (AllReady=%d, Count=%d, MinPlayers=%d)"),
   595→			bCanStart, bAllReady, PlayerCount, MinPlayers);
   596→	}
   597→	else
   598→	{
   599→		// 호스트가 아니면 버튼 비활성화
   600→		StartGameButton->SetIsEnabled(false);
   601→
   602→		if (StartGameStatusText)
   603→		{
   604→			StartGameStatusText->SetVisibility(ESlateVisibility::Collapsed);
   605→		}
