   656→void UWaitingRoomHUDWidget::UpdateHostSettingsPanelVisibility()
   657→{
   658→	if (!HostSettingsPanel)
   659→	{
   660→		return;
   661→	}
   662→
   663→	bool bIsHost = false;
   664→
   665→	// 1. SessionManager에서 호스트 여부 확인
   666→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   667→	if (GameInstance && GameInstance->GetSessionManager())
   668→	{
   669→		bIsHost = GameInstance->GetSessionManager()->IsHost();
   670→	}
   671→
   672→	// 2. 추가 검증: Listen Server인지 확인 (클라이언트에서 잘못된 bIsHost 값 방지)
   673→	UWorld* World = GetWorld();
   674→	if (World)
   675→	{
   676→		ENetMode NetMode = World->GetNetMode();
   677→		// 클라이언트(NM_Client)는 절대 호스트가 아님
   678→		if (NetMode == NM_Client)
   679→		{
   680→			bIsHost = false;
   681→		}
   682→		// Listen Server(NM_ListenServer)만 호스트임
   683→		else if (NetMode == NM_ListenServer || NetMode == NM_DedicatedServer)
   684→		{
   685→			// SessionManager 값 유지
   686→		}
   687→		else if (NetMode == NM_Standalone)
   688→		{
   689→			// 싱글플레이는 호스트 설정 불필요
   690→			bIsHost = false;
   691→		}
   692→	}
   693→
   694→	// 호스트만 설정 패널 표시 (클라이언트는 Display Text로 확인)
   695→	HostSettingsPanel->SetVisibility(bIsHost ? ESlateVisibility::Visible : ESlateVisibility::Collapsed);
   696→
   697→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: HostSettingsPanel visible=%s (bIsHost=%d, NetMode=%d)"),
   698→		bIsHost ? TEXT("Yes") : TEXT("No"), bIsHost, World ? (int32)World->GetNetMode() : -1);
   699→}
