   701→void UWaitingRoomHUDWidget::UpdateMapComboBoxForGameMode(const FString& GameModeId)
   702→{
   703→	if (!MapComboBox)
   704→	{
   705→		return;
   706→	}
   707→
   708→	MapComboBox->ClearOptions();
   709→	MapOptionDisplayToValue.Empty();
   710→
   711→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   712→	if (!DevSettings || DevSettings->MinigameCatalog.IsNull())
   713→	{
   714→		return;
   715→	}
   716→
   717→	UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
   718→	if (!Catalog)
   719→	{
   720→		return;
   721→	}
   722→
   723→	const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*GameModeId));
   724→	if (Def)
   725→	{
   726→		for (const FWjWorldMinigameMapOption& Option : Def->MapOptions)
   727→		{
   728→			FString DisplayName = Option.DisplayName.ToString();
   729→			FString OptionValue = Option.OptionValue;
   730→
   731→			MapComboBox->AddOption(DisplayName);
   732→			MapOptionDisplayToValue.Add(DisplayName, OptionValue);
   733→		}
   734→	}
   735→
   736→	// ApproachingWall인 경우 유저 레이아웃도 추가
   737→	if (GameModeId == TEXT("ApproachingWall"))
   738→	{
   739→		if (!DevSettings->WallDescriptionAsset.IsNull())
   740→		{
   741→			UWjWorldWallDescriptionDataAsset* WallAsset = DevSettings->WallDescriptionAsset.LoadSynchronous();
   742→			if (WallAsset)
   743→			{
   744→				TArray<FWjWorldWallDescription> UserLayouts;
   745→				WallAsset->ScanUserWallLayouts(UserLayouts);
   746→
   747→				for (const FWjWorldWallDescription& Layout : UserLayouts)
   748→				{
   749→					FString DisplayName = Layout.WallName;
   750→					DisplayName.RemoveFromStart(TEXT("User_"));
   751→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   752→
   753→					MapComboBox->AddOption(DisplayStr);
   754→					MapOptionDisplayToValue.Add(DisplayStr, Layout.WallName);
   755→				}
   756→
   757→				UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Added %d AW user layouts"), UserLayouts.Num());
   758→			}
   759→		}
   760→	}
   761→
   762→	// JumpMap인 경우 유저 레이아웃도 추가
   763→	if (GameModeId == TEXT("JumpMap"))
   764→	{
   765→		if (!DevSettings->JumpMapLayoutDataAsset.IsNull())
   766→		{
   767→			UJumpMapLayoutDataAsset* LayoutAsset = DevSettings->JumpMapLayoutDataAsset.LoadSynchronous();
   768→			if (LayoutAsset)
   769→			{
   770→				TArray<FJumpMapLayout> UserLayouts;
   771→				LayoutAsset->ScanUserJumpMapLayouts(UserLayouts);
   772→
   773→				for (const FJumpMapLayout& Layout : UserLayouts)
   774→				{
   775→					FString DisplayName = Layout.LayoutName;
   776→					DisplayName.RemoveFromStart(TEXT("User_"));
   777→					FString DisplayStr = FString::Printf(TEXT("[User] %s"), *DisplayName);
   778→
   779→					MapComboBox->AddOption(DisplayStr);
   780→					MapOptionDisplayToValue.Add(DisplayStr, Layout.LayoutName);
   781→				}
   782→
   783→				UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Added %d JumpMap user layouts"), UserLayouts.Num());
   784→			}
   785→		}
   786→	}
   787→
   788→	if (MapComboBox->GetOptionCount() > 0)
   789→	{
   790→		MapComboBox->SetSelectedIndex(0);
   791→	}
   792→
   793→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Map options updated for GameMode '%s' - %d options"),
   794→		*GameModeId, MapComboBox->GetOptionCount());
   795→}
