   808→void UWaitingRoomHUDWidget::OnApplySettingsClicked()
   809→{
   810→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget::OnApplySettingsClicked START ==="));
   811→
   812→	if (!CachedGameState)
   813→	{
   814→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: CachedGameState is NULL!"));
   815→		return;
   816→	}
   817→	if (!GameModeComboBox)
   818→	{
   819→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: GameModeComboBox is NULL!"));
   820→		return;
   821→	}
   822→	if (!MapComboBox)
   823→	{
   824→		UE_LOG(LogWjWorld, Error, TEXT("WaitingRoomHUDWidget: MapComboBox is NULL!"));
   825→		return;
   826→	}
   827→
   828→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   829→	if (!GameInstance || !GameInstance->GetSessionManager() || !GameInstance->GetSessionManager()->IsHost())
   830→	{
   831→		UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Only host can change settings (IsHost=%d)"),
   832→			GameInstance && GameInstance->GetSessionManager() ? GameInstance->GetSessionManager()->IsHost() : false);
   833→		return;
   834→	}
   835→
   836→	FRoomSettings OldSettings = CachedGameState->GetRoomSettings();
   837→	FRoomSettings NewSettings = OldSettings;
   838→
   839→	FString SelectedGameMode = GameModeComboBox->GetSelectedOption();
   840→	NewSettings.GameMode = SelectedGameMode;
   841→
   842→	FString SelectedMapDisplay = MapComboBox->GetSelectedOption();
   843→	if (const FString* MapValue = MapOptionDisplayToValue.Find(SelectedMapDisplay))
   844→	{
   845→		NewSettings.MapName = *MapValue;
   846→	}
   847→	else
   848→	{
   849→		NewSettings.MapName = SelectedMapDisplay;
   850→	}
   851→
   852→	UE_LOG(LogWjWorld, Warning, TEXT("WaitingRoomHUDWidget: Applying settings change:"));
   853→	UE_LOG(LogWjWorld, Warning, TEXT("  GameMode: '%s' -> '%s'"), *OldSettings.GameMode, *NewSettings.GameMode);
   854→	UE_LOG(LogWjWorld, Warning, TEXT("  MapName: '%s' -> '%s'"), *OldSettings.MapName, *NewSettings.MapName);
   855→
   856→	CachedGameState->UpdateRoomSettings(NewSettings);
   857→
   858→	// ⭐ 호스트 로컬에서 Display Text 직접 업데이트 (델리게이트 타이밍 안전장치)
   859→	UpdateRoomInfo(&NewSettings);
   860→
   861→	UE_LOG(LogWjWorld, Warning, TEXT("=== WaitingRoomHUDWidget::OnApplySettingsClicked END ==="));
   862→}
