   864→void UWaitingRoomHUDWidget::ApplyCurrentUISettings()
   865→{
   866→	// 호스트가 아니면 무시
   867→	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
   868→	if (!GameInstance || !GameInstance->GetSessionManager() || !GameInstance->GetSessionManager()->IsHost())
   869→	{
   870→		return;
   871→	}
   872→
   873→	// 필요한 컴포넌트가 없으면 무시
   874→	if (!CachedGameState || !GameModeComboBox || !MapComboBox)
   875→	{
   876→		return;
   877→	}
   878→
   879→	FRoomSettings NewSettings = CachedGameState->GetRoomSettings();
   880→
   881→	// 현재 UI에서 선택된 게임 모드
   882→	FString SelectedGameMode = GameModeComboBox->GetSelectedOption();
   883→	if (!SelectedGameMode.IsEmpty())
   884→	{
   885→		NewSettings.GameMode = SelectedGameMode;
   886→	}
   887→
   888→	// 현재 UI에서 선택된 맵
   889→	FString SelectedMapDisplay = MapComboBox->GetSelectedOption();
   890→	if (const FString* MapValue = MapOptionDisplayToValue.Find(SelectedMapDisplay))
   891→	{
   892→		NewSettings.MapName = *MapValue;
   893→	}
   894→	else if (!SelectedMapDisplay.IsEmpty())
   895→	{
   896→		NewSettings.MapName = SelectedMapDisplay;
   897→	}
   898→
   899→	UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Auto-applying UI settings before game start - GameMode: '%s', Map: '%s'"),
   900→		*NewSettings.GameMode, *NewSettings.MapName);
   901→
   902→	CachedGameState->UpdateRoomSettings(NewSettings);
   903→}
