   271→void AWjWorldGameModeWaitingRoom::LoadHostLayoutToGameState()
   272→{
   273→	if (!HasAuthority())
   274→	{
   275→		return;
   276→	}
   277→
   278→	AWjWorldGameStateWaitingRoom* WaitingRoomGameState = GetGameState<AWjWorldGameStateWaitingRoom>();
   279→	if (!WaitingRoomGameState)
   280→	{
   281→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("WjWorldGameModeWaitingRoom: GameState not found"));
   282→		return;
   283→	}
   284→
   285→	// 호스트의 로컬 SaveGame 로드
   286→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   287→		UGameplayStatics::LoadGameFromSlot(TEXT("LobbyLayout"), 0)
   288→	);
   289→
   290→	if (SaveGame && SaveGame->PlacedObjects.Num() > 0)
   291→	{
   292→		WaitingRoomGameState->SetPlacedObjects(SaveGame->PlacedObjects);
   293→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeWaitingRoom: Host layout loaded to GameState (%d objects)"),
   294→			SaveGame->PlacedObjects.Num());
   295→	}
   296→	else
   297→	{
   298→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeWaitingRoom: No saved layout found for host"));
   299→	}
   300→}
