    67→
    68→	// SessionManager에도 반영 (StartGame에서 사용)
    69→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
    70→	{
    71→		if (GI->GetSessionManager())
    72→		{
    73→			GI->GetSessionManager()->UpdateLastRoomSettings(NewSettings);
    74→		}
    75→	}
    76→}
