   163→void AWjWorldGameStateWaitingRoom::OnRep_RoomSettings()
   164→{
   165→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Room settings replicated - %s"), *RoomSettings.RoomName);
   166→
   167→	// 클라이언트 측에서도 캐시 (호스트 마이그레이션용)
   168→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   169→	{
   170→		GI->CacheRoomSettings(RoomSettings);
   171→	}
   172→
   173→	// 이벤트 브로드캐스트
   174→	OnRoomInfoChanged.Broadcast(RoomSettings);
   175→}
   176→
   177→void AWjWorldGameStateWaitingRoom::AddPlayerState(APlayerState* PlayerState)
   178→{
   179→	Super::AddPlayerState(PlayerState);
   180→
   181→	AWjWorldPlayerStateBase* WjPS = Cast<AWjWorldPlayerStateBase>(PlayerState);
   182→	if (WjPS)
   183→	{
   184→		FString PlayerName = WjPS->GetPlayerName();
   185→
   186→		// ⭐ PlayerName 업데이트 이벤트 구독
   187→		WjPS->OnPlayerNameUpdated.AddDynamic(this, &AWjWorldGameStateWaitingRoom::OnPlayerNameUpdated);
   188→
   189→		// ⭐ Ready 상태 변경 이벤트 구독
   190→		WjPS->OnReadyStateChanged.AddDynamic(this, &AWjWorldGameStateWaitingRoom::OnPlayerReadyStateChanged);
   191→
   192→		// ⭐ 이름이 비어있으면 아직 초기화 중 (나중에 OnPlayerNameUpdated 호출됨)
   193→		if (PlayerName.IsEmpty())
   194→		{
   195→			UE_LOG(LogWjWorld, Warning, TEXT("GameStateWaitingRoom: Player added with empty name (ID: %d) - Waiting for replication"), 
   196→				WjPS->GetPlayerId());
   197→			return;
   198→		}
   199→
   200→		// 첫 번째 플레이어를 호스트로 설정
   201→		if (HostPlayerID == -1)
   202→		{
   203→			HostPlayerID = WjPS->GetPlayerId();
   204→			UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Host set to PlayerID %d"), HostPlayerID);
   205→		}
   206→
   207→		UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Player added - %s (ID: %d, Total: %d)"),
   208→			*PlayerName, WjPS->GetPlayerId(), GetPlayerCount());
   209→	}
   210→
   211→	// 플레이어 목록 변경 브로드캐스트
   212→	BroadcastPlayerListChanged();
   213→}
   214→
   215→void AWjWorldGameStateWaitingRoom::RemovePlayerState(APlayerState* PlayerState)
   216→{
   217→	AWjWorldPlayerStateBase* WjPS = Cast<AWjWorldPlayerStateBase>(PlayerState);
   218→	if (WjPS)
   219→	{
   220→		// 이벤트 구독 해제
   221→		WjPS->OnPlayerNameUpdated.RemoveDynamic(this, &AWjWorldGameStateWaitingRoom::OnPlayerNameUpdated);
   222→		WjPS->OnReadyStateChanged.RemoveDynamic(this, &AWjWorldGameStateWaitingRoom::OnPlayerReadyStateChanged);
   223→
   224→		UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Player removed - %s (ID: %d, Remaining: %d)"),
   225→			*WjPS->GetPlayerName(), WjPS->GetPlayerId(), GetPlayerCount() - 1);
   226→
   227→		// 호스트가 나갔다면 새로운 호스트 지정
   228→		if (WjPS->GetPlayerId() == HostPlayerID && PlayerArray.Num() > 1)
   229→		{
   230→			// 나가는 플레이어를 제외한 첫 번째 유효한 플레이어를 새 호스트로
   231→			for (APlayerState* PS : PlayerArray)
   232→			{
   233→				AWjWorldPlayerStateBase* NextHost = Cast<AWjWorldPlayerStateBase>(PS);
   234→				if (NextHost && NextHost != WjPS && !NextHost->GetPlayerName().IsEmpty())
   235→				{
   236→					HostPlayerID = NextHost->GetPlayerId();
   237→					UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: New host set to PlayerID %d"), HostPlayerID);
   238→					break;
   239→				}
   240→			}
   241→		}
   242→	}
   243→
   244→	Super::RemovePlayerState(PlayerState);
   245→
   246→	// 플레이어 목록 변경 브로드캐스트
   247→	BroadcastPlayerListChanged();
   248→}
   249→
   250→void AWjWorldGameStateWaitingRoom::OnPlayerNameUpdated(const FString& PlayerName)
   251→{
   252→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: OnPlayerNameUpdated called - %s"), *PlayerName);
   253→
   254→	// 플레이어 목록 재브로드캐스트
   255→	BroadcastPlayerListChanged();
   256→}
   257→
   258→void AWjWorldGameStateWaitingRoom::OnPlayerReadyStateChanged(int32 PlayerID, bool bIsReady)
   259→{
   260→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: OnPlayerReadyStateChanged - PlayerID: %d, IsReady: %s"),
   261→		PlayerID, bIsReady ? TEXT("true") : TEXT("false"));
   262→
   263→	// 플레이어 목록 재브로드캐스트 (Ready 상태 포함)
   264→	BroadcastPlayerListChanged();
   265→}
   266→
   267→void AWjWorldGameStateWaitingRoom::BroadcastPlayerListChanged()
   268→{
   269→	TArray<FPlayerDisplayInfo> PlayerList = GetPlayerList();
   270→
   271→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Broadcasting player list change - %d players"), PlayerList.Num());
   272→
   273→	// GameInstance에 플레이어 목록 캐시 (호스트 마이그레이션용)
   274→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   275→	{
   276→		GI->CachePlayerList(PlayerList);
   277→	}
   278→
   279→	// 이벤트 브로드캐스트
   280→	OnPlayerListChanged.Broadcast(PlayerList);
   281→}
