   113→void UWjWorldGameRuleBase::OnGameEnd()
   114→{
   115→	if (!HasAuthority()) return;
   116→
   117→	UWorld* World = GetWorld();
   118→	if (World)
   119→	{
   120→		// 세션 종료 (InProgress → Ended) - WaitingRoom 복귀 후 다시 StartSession 가능하게
   121→		if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(World->GetGameInstance()))
   122→		{
   123→			GI->EndGame();
   124→		}
   125→
   126→		// ServerTravel URL 미리 계산 (타이머 콜백에서 this 접근 문제 방지)
   127→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   128→		FString TravelURL = Settings->GetWaitingRoomServerTravelURL();
   129→
   130→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase::OnGameEnd - Will travel to: %s in %f seconds"), *TravelURL, SecondsForGotoWaitingRoom);
   131→
   132→		// Lobby 맵을 사용하되 GameMode는 WaitingRoom으로 오버라이드
   133→		// World를 WeakPtr로 캡처하여 타이머 콜백에서 안전하게 접근
   134→		TWeakObjectPtr<UWorld> WeakWorld = World;
   135→		World->GetTimerManager().SetTimer(GotoWaitingRoomHandle, FTimerDelegate::CreateLambda([WeakWorld, TravelURL]() {
