   151→void UWjWorldGameRuleJumpMap::SpawnActorsFromLayout(const FJumpMapLayout& Layout)
   152→{
   153→	UWorld* World = GetWorld();
   154→	if (!World) return;
   155→
   156→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   157→
   158→	for (const FJumpMapLayoutEntry& Entry : Layout.Objects)
   159→	{
   160→		// BP 프로퍼티에서 먼저 조회
   161→		TSubclassOf<AActor> ActorClass = nullptr;
   162→		if (const TSubclassOf<AActor>* Found = ObjectIdToActorClassMap.Find(Entry.ObjectId))
   163→		{
   164→			ActorClass = *Found;
   165→		}
   166→		else if (DevSettings)
   167→		{
   168→			// DeveloperSettings 폴백
   169→			if (const TSoftClassPtr<AJumpMapActorBase>* SoftFound =
   170→				DevSettings->JumpMapObjectIdToClassMap.Find(Entry.ObjectId))
   171→			{
   172→				ActorClass = SoftFound->LoadSynchronous();
   173→			}
   174→		}
   175→
   176→		if (!ActorClass)
   177→		{
   178→			UE_LOG(LogWjWorld, Warning, TEXT("GameRuleJumpMap: No class for ObjectId '%s'"), *Entry.ObjectId.ToString());
   179→			continue;
   180→		}
   181→
   182→		FActorSpawnParameters SpawnParams;
   183→		SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
   184→
   185→		AActor* NewActor = World->SpawnActor<AActor>(ActorClass, Entry.Transform, SpawnParams);
   186→		if (NewActor)
   187→		{
   188→			// JumpMapActorBase인 경우 CustomProperties 적용
   189→			AJumpMapActorBase* JumpMapActor = Cast<AJumpMapActorBase>(NewActor);
   190→			if (JumpMapActor)
   191→			{
   192→				JumpMapActor->InitializeFromLayoutEntry(Entry.Transform);
   193→				JumpMapActor->ApplySerializedProperties(Entry.CustomProperties);
   194→			}
   195→
   196→			SpawnedGameplayActors.Add(NewActor);
   197→		}
   198→	}
   199→
   200→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Spawned %d actors from layout"), SpawnedGameplayActors.Num());
   201→}
