   245→void AWjWorldGameModeWaitingRoom::LoadPlacementCatalog()
   246→{
   247→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   248→	if (!Settings || Settings->PlaceableObjectCatalog.IsNull())
   249→	{
   250→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeWaitingRoom: No PlaceableObjectCatalog configured"));
