   259→	}
   260→
   261→	// GameState에도 카탈로그 설정 (GameStateWaitingRoom은 GameStateLobby 상속)
   262→	AWjWorldGameStateWaitingRoom* WaitingRoomGameState = GetGameState<AWjWorldGameStateWaitingRoom>();
   263→	if (WaitingRoomGameState)
   264→	{
   265→		WaitingRoomGameState->SetCatalog(CachedPlacementCatalog);
   266→	}
   267→
   268→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeWaitingRoom: Placement catalog loaded"));
   269→}
