void UWaitingRoomHUDWidget::UpdateStartGameButton()
{
	if (!StartGameButton || !CachedGameState)
	{
		return;
	}

	// 호스트 여부 확인
	UWjWorldGameInstance* GameInstance = Cast<UWjWorldGameInstance>(GetGameInstance());
	if (!GameInstance || !GameInstance->GetSessionManager())
	{
		return;
	}

	bool bIsHost = GameInstance->GetSessionManager()->IsHost();

	if (bIsHost)
	{
		// 호스트는 모든 플레이어가 준비되었을 때만 게임 시작 가능
		bool bAllReady = CachedGameState->AreAllPlayersReady();
		int32 PlayerCount = CachedGameState->GetPlayerCount();

		// 카탈로그에서 최소 인원 조회
		int32 MinPlayers = 1;
		const FRoomSettings& CurrentSettings = CachedGameState->GetRoomSettings();
		const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
		if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
		{
			UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
			if (Catalog)
			{
				const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*CurrentSettings.GameMode));
				if (Def)
				{
					MinPlayers = Def->MinimumPlayers;
				}
			}
		}

		bool bEnoughPlayers = (PlayerCount >= MinPlayers);
		bool bCanStart = bAllReady && bEnoughPlayers;

		StartGameButton->SetIsEnabled(bCanStart);

		// 시작 불가 사유 표시
		if (StartGameStatusText)
		{
			if (!bEnoughPlayers)
			{
				StartGameStatusText->SetText(FText::FromString(
					FString::Printf(TEXT("Need %d+ players (%d/%d)"), MinPlayers, PlayerCount, MinPlayers)));
				StartGameStatusText->SetVisibility(ESlateVisibility::Visible);
			}
			else if (!bAllReady)
			{
				StartGameStatusText->SetText(FText::FromString(TEXT("Waiting for all players to ready")));
				StartGameStatusText->SetVisibility(ESlateVisibility::Visible);
			}
			else
			{
				StartGameStatusText->SetVisibility(ESlateVisibility::Collapsed);
			}
		}

		UE_LOG(LogWjWorld, Log, TEXT("WaitingRoomHUDWidget: Start button enabled = %d (AllReady=%d, Count=%d, MinPlayers=%d)"),
			bCanStart, bAllReady, PlayerCount, MinPlayers);
	}
	else
	{
		// 호스트가 아니면 버튼 비활성화
		StartGameButton->SetIsEnabled(false);

		if (StartGameStatusText)
		{
			StartGameStatusText->SetVisibility(ESlateVisibility::Collapsed);
		}
	}
}

void UWaitingRoomHUDWidget::InitializeHostSettingsPanel()
